mapper.select:
SELECT ht.task_def_key_ "preActId", ht.name_ "preAct", ht.end_time_ "preEndDate", ht.assignee_ "preUser" FROM act_hi_taskinst ht WHERE ht.DELETE_REASON_ != 'delete' AND ht.DELETE_REASON_ != 'reback' AND ht.DELETE_REASON_ != 'TansunBackDelete' AND ht.proc_inst_id_ = #{processInstanceId} AND ht.TASK_DEF_KEY_ != #{actId}
AND ht.end_time_ <= to_timestamp(#{createTime},'YYYY-MM-DD HH24:MI:ss.ff3')
AND ht.end_time_ <= #{createTime}
ORDER BY ht.end_time_ desc

mapper.update:
update ACT_HI_TASKINST RES
set  RES.ASSIGNEE_= #{assignee}
where RES.ID_= #{taskId}

mapper.select:
select ${sliceColumnName} from act_hi_taskinst where

    id_ = #{taskId}


    AND PROC_INST_ID_ = #{processInstanceId}

order by start_time_ desc

    and rownum = 1


    limit 1
